/* Big Dolphin 10 by Kemboi-Dun — https://uiverse.io/Kemboi-Dun/big-dolphin-10 */
.loader {
  height: 5cm;
  width: 5cm;
  border-radius: 1rem;

  box-shadow: inset 0 0 0 #0a7cbe;
  animation: load 4s ease infinite;
}

@keyframes load {

  0% {
    box-shadow: inset -5cm -2.5cm 0 #0a7cbe;
  }

  25% {
    box-shadow: inset 5cm -2.5cm 0 #0a7cbe;
  }

  25.01% {
    box-shadow: inset 2.5cm -5cm 0 #0a7cbe;
  }

  50% {
    box-shadow: inset 2.5cm 5cm 0 #0a7cbe;
  }

  50.01% {
    box-shadow: inset 5cm 2.5cm 0 #0a7cbe;
  }

  75% {
    box-shadow: inset -5cm 2.5cm 0 #0a7cbe;
  }

  75.01% {
    box-shadow: inset -2.5cm 5cm 0 #0a7cbe;
  }

  100% {
    box-shadow: inset -2.5cm -5cm 0 #0a7cbe;
  }
}
